// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import { AccessControlUpgradeable } from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/// @title Pauser
/// @notice Contract for managing pause states of various system functions
/// @author WalletConnect
contract Pauser is Initializable, AccessControlUpgradeable {
    /// @notice Emitted when a flag has been updated
    /// @param selector The selector of the flag that was updated
    /// @param isPaused The new value of the flag
    /// @param flagName The name of the flag that was updated
    event FlagUpdated(bytes4 indexed selector, bool indexed isPaused, string flagName);

    error InvalidInput();

    /// @notice Role for pausing functions
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Role for unpausing functions
    bytes32 public constant UNPAUSER_ROLE = keccak256("UNPAUSER_ROLE");

    /// @notice Flag indicating if stakeWeight is paused
    bool public isStakeWeightPaused;

    /// @notice Flag indicating if submit oracle records is paused
    bool public isSubmitOracleRecordsPaused;

    /// @notice Flag indicating if locked token staker is paused
    bool public isLockedTokenStakerPaused;

    /// @notice Flag indicating if node reward manager is paused
    bool public isNodeRewardManagerPaused;

    /// @notice Flag indicating if wallet reward manager is paused
    bool public isWalletRewardManagerPaused;

    /// @notice Flag indicating if staking reward distributor is paused
    bool public isStakingRewardDistributorPaused;

    /// @notice Configuration for contract initialization
    struct Init {
        address admin;
        address pauser;
    }

    /// @notice Initializes the contract
    /// @dev MUST be called during the contract upgrade to set up the proxies state
    /// @param init Initialization parameters
    function initialize(Init memory init) external initializer {
        __AccessControl_init();
        _grantRole(DEFAULT_ADMIN_ROLE, init.admin);
        if (init.pauser == address(0)) {
            revert InvalidInput();
        }
        _grantRole(PAUSER_ROLE, init.pauser);
        _grantRole(UNPAUSER_ROLE, init.admin);
    }

    /// @notice Pauses or unpauses staking
    /// @param isPaused The new pause state
    function setIsStakeWeightPaused(bool isPaused) external {
        if (isPaused) {
            _checkRole(PAUSER_ROLE);
        } else {
            _checkRole(UNPAUSER_ROLE);
        }
        _setIsStakeWeightPaused(isPaused);
    }

    /// @notice Pauses or unpauses locked token staker
    /// @param isPaused The new pause state
    function setIsLockedTokenStakerPaused(bool isPaused) external {
        if (isPaused) {
            _checkRole(PAUSER_ROLE);
        } else {
            _checkRole(UNPAUSER_ROLE);
        }
        _setIsLockedTokenStakerPaused(isPaused);
    }

    /// @notice Pauses or unpauses submit oracle records
    /// @param isPaused The new pause state
    function setIsSubmitOracleRecordsPaused(bool isPaused) external {
        if (isPaused) {
            _checkRole(PAUSER_ROLE);
        } else {
            _checkRole(UNPAUSER_ROLE);
        }
        _setIsSubmitOracleRecordsPaused(isPaused);
    }

    /// @notice Pauses or unpauses node reward manager
    /// @param isPaused The new pause state
    function setIsNodeRewardManagerPaused(bool isPaused) external {
        if (isPaused) {
            _checkRole(PAUSER_ROLE);
        } else {
            _checkRole(UNPAUSER_ROLE);
        }
        _setIsNodeRewardManagerPaused(isPaused);
    }

    /// @notice Pauses or unpauses wallet reward manager
    /// @param isPaused The new pause state
    function setIsWalletRewardManagerPaused(bool isPaused) external {
        if (isPaused) {
            _checkRole(PAUSER_ROLE);
        } else {
            _checkRole(UNPAUSER_ROLE);
        }
        _setIsWalletRewardManagerPaused(isPaused);
    }

    /// @notice Pauses or unpauses staking reward distributor
    /// @param isPaused The new pause state
    function setIsStakingRewardDistributorPaused(bool isPaused) external {
        if (isPaused) {
            _checkRole(PAUSER_ROLE);
        } else {
            _checkRole(UNPAUSER_ROLE);
        }
        _setIsStakingRewardDistributorPaused(isPaused);
    }

    /// @dev Sets the node reward manager pause state
    /// @param isPaused The new pause state
    function _setIsNodeRewardManagerPaused(bool isPaused) private {
        isNodeRewardManagerPaused = isPaused;
        emit FlagUpdated({
            selector: this.isNodeRewardManagerPaused.selector,
            isPaused: isPaused,
            flagName: "isNodeRewardManagerPaused"
        });
    }

    /// @dev Sets the wallet reward manager pause state
    /// @param isPaused The new pause state
    function _setIsWalletRewardManagerPaused(bool isPaused) private {
        isWalletRewardManagerPaused = isPaused;
        emit FlagUpdated({
            selector: this.isWalletRewardManagerPaused.selector,
            isPaused: isPaused,
            flagName: "isWalletRewardManagerPaused"
        });
    }

    /// @notice Pauses all actions
    function pauseAll() external onlyRole(PAUSER_ROLE) {
        _setIsStakeWeightPaused(true);
        _setIsSubmitOracleRecordsPaused(true);
        _setIsLockedTokenStakerPaused(true);
        _setIsNodeRewardManagerPaused(true);
        _setIsWalletRewardManagerPaused(true);
        _setIsStakingRewardDistributorPaused(true);
    }

    /// @notice Unpauses all actions
    function unpauseAll() external onlyRole(UNPAUSER_ROLE) {
        _setIsStakeWeightPaused(false);
        _setIsSubmitOracleRecordsPaused(false);
        _setIsLockedTokenStakerPaused(false);
        _setIsNodeRewardManagerPaused(false);
        _setIsWalletRewardManagerPaused(false);
        _setIsStakingRewardDistributorPaused(false);
    }

    /// @dev Sets the staking pause state
    /// @param isPaused The new pause state
    function _setIsStakeWeightPaused(bool isPaused) private {
        isStakeWeightPaused = isPaused;
        emit FlagUpdated({
            selector: this.isStakeWeightPaused.selector,
            isPaused: isPaused,
            flagName: "isStakeWeightPaused"
        });
    }

    /// @dev Sets the submit oracle records pause state
    /// @param isPaused The new pause state
    function _setIsSubmitOracleRecordsPaused(bool isPaused) private {
        isSubmitOracleRecordsPaused = isPaused;
        emit FlagUpdated({
            selector: this.isSubmitOracleRecordsPaused.selector,
            isPaused: isPaused,
            flagName: "isSubmitOracleRecordsPaused"
        });
    }

    /// @dev Sets the locked token staker pause state
    /// @param isPaused The new pause state
    function _setIsLockedTokenStakerPaused(bool isPaused) private {
        isLockedTokenStakerPaused = isPaused;
        emit FlagUpdated({
            selector: this.isLockedTokenStakerPaused.selector,
            isPaused: isPaused,
            flagName: "isLockedTokenStakerPaused"
        });
    }

    /// @dev Sets the staking reward distributor pause state
    /// @param isPaused The new pause state
    function _setIsStakingRewardDistributorPaused(bool isPaused) private {
        isStakingRewardDistributorPaused = isPaused;
        emit FlagUpdated({
            selector: this.isStakingRewardDistributorPaused.selector,
            isPaused: isPaused,
            flagName: "isStakingRewardDistributorPaused"
        });
    }
}

src/WalletConnectConfig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import { AccessControlUpgradeable } from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/// @title WalletConnectConfig
/// @notice Configuration contract for the WalletConnect system
/// @author WalletConnect
contract WalletConnectConfig is Initializable, AccessControlUpgradeable {
    /// @notice Error thrown when attempting to set an identical value
    error IdenticalValue();

    /// @notice Error thrown when an invalid address is provided
    error InvalidAddress();

    /// @notice Emitted when a contract address is set
    /// @param key The key identifying the contract
    /// @param val The new contract address
    event ContractSet(bytes32 indexed key, address val);

    /// @notice Role for administrative actions
    /// @notice Configuration for contract initialization
    struct Init {
        address admin;
    }

    // Storage
    mapping(bytes32 => address) private _contractsMap;

    bytes32 public constant L2WCT_TOKEN = keccak256("L2WCT_TOKEN");
    bytes32 public constant PERMISSIONED_NODE_REGISTRY = keccak256("PERMISSIONED_NODE_REGISTRY");
    bytes32 public constant NODE_REWARD_MANAGER = keccak256("NODE_REWARD_MANAGER");
    bytes32 public constant WALLET_REWARD_MANAGER = keccak256("WALLET_REWARD_MANAGER");
    bytes32 public constant STAKE_WEIGHT = keccak256("STAKE_WEIGHT");
    bytes32 public constant ORACLE = keccak256("ORACLE");
    bytes32 public constant PAUSER = keccak256("PAUSER");
    bytes32 public constant STAKING_REWARD_DISTRIBUTOR = keccak256("STAKING_REWARD_DISTRIBUTOR");

    /// @notice Initializes the contract
    /// @dev MUST be called during the contract upgrade to set up the proxies state
    /// @param init Initialization parameters
    function initialize(Init memory init) public initializer {
        __AccessControl_init();
        _grantRole(DEFAULT_ADMIN_ROLE, init.admin);
    }

    /// @notice Gets the L2WCT token address
    /// @return The address of the L2WCT token contract
    function getL2wct() external view returns (address) {
        return _contractsMap[L2WCT_TOKEN];
    }

    /// @notice Gets the Pauser address
    /// @return The address of the Pauser contract
    function getPauser() external view returns (address) {
        return _contractsMap[PAUSER];
    }

    /// @notice Gets the Permissioned Node Registry address
    /// @return The address of the Permissioned Node Registry contract
    function getPermissionedNodeRegistry() external view returns (address) {
        return _contractsMap[PERMISSIONED_NODE_REGISTRY];
    }

    /// @notice Gets the Node Reward Manager address
    /// @return The address of the Node Reward Manager contract
    function getNodeRewardManager() external view returns (address) {
        return _contractsMap[NODE_REWARD_MANAGER];
    }

    /// @notice Gets the Wallet Reward Manager address
    /// @return The address of the Wallet Reward Manager contract
    function getWalletRewardManager() external view returns (address) {
        return _contractsMap[WALLET_REWARD_MANAGER];
    }

    /// @notice Gets the StakeWeight address
    /// @return The address of the StakeWeight contract
    function getStakeWeight() external view returns (address) {
        return _contractsMap[STAKE_WEIGHT];
    }

    /// @notice Gets the Oracle address
    /// @return The address of the Oracle contract
    function getOracle() external view returns (address) {
        return _contractsMap[ORACLE];
    }

    /// @notice Gets the StakingRewardDistributor address
    /// @return The address of the StakingRewardDistributor contract
    function getStakingRewardDistributor() external view returns (address) {
        return _contractsMap[STAKING_REWARD_DISTRIBUTOR];
    }

    /// @notice Updates the L2WCT token address
    /// @param l2wct The new L2WCT token address
    function updateL2wct(address l2wct) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setContract({ key: L2WCT_TOKEN, val: l2wct });
    }

    /// @notice Updates the Pauser address
    /// @param pauser The new Pauser address
    function updatePauser(address pauser) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setContract({ key: PAUSER, val: pauser });
    }

    /// @notice Updates the Permissioned Node Registry address
    /// @param permissionedNodeRegistry The new Permissioned Node Registry address
    function updatePermissionedNodeRegistry(address permissionedNodeRegistry) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setContract({ key: PERMISSIONED_NODE_REGISTRY, val: permissionedNodeRegistry });
    }

    /// @notice Updates the Node Reward Manager address
    /// @param nodeRewardManager The new Node Reward Manager address
    function updateNodeRewardManager(address nodeRewardManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setContract({ key: NODE_REWARD_MANAGER, val: nodeRewardManager });
    }

    /// @notice Updates the Wallet Reward Manager address
    /// @param walletRewardManager The new Wallet Reward Manager address
    function updateWalletRewardManager(address walletRewardManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setContract({ key: WALLET_REWARD_MANAGER, val: walletRewardManager });
    }

    /// @notice Updates the Oracle address
    /// @param oracle The new Oracle address
    function updateOracle(address oracle) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setContract({ key: ORACLE, val: oracle });
    }

    /// @notice Updates the StakeWeight address
    /// @param stakeWeight The new StakeWeight address
    function updateStakeWeight(address stakeWeight) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setContract({ key: STAKE_WEIGHT, val: stakeWeight });
    }

    /// @notice Updates the StakingRewardDistributor address
    /// @param stakingRewardDistributor The new StakingRewardDistributor address
    function updateStakingRewardDistributor(address stakingRewardDistributor) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setContract({ key: STAKING_REWARD_DISTRIBUTOR, val: stakingRewardDistributor });
    }

    /// @notice Checks if the given address is a recognized WalletConnect contract
    /// @param addr The address to check
    /// @param contractName The name of the contract to check against
    /// @return True if the address matches the stored contract address, false otherwise
    function isWalletConnectContract(address addr, bytes32 contractName) external view returns (bool) {
        return (addr == _contractsMap[contractName]);
    }

    /// @dev Sets a contract address
    /// @param key The key identifying the contract
    /// @param val The new contract address
    function _setContract(bytes32 key, address val) private {
        if (val == address(0)) {
            revert InvalidAddress();
        }
        if (_contractsMap[key] == val) {
            revert IdenticalValue();
        }
        _contractsMap[key] = val;
        emit ContractSet({ key: key, val: val });
    }
}

src/L2WCT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import { ERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import { ERC20PermitUpgradeable } from
    "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PermitUpgradeable.sol";
import { ERC20VotesUpgradeable } from
    "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20VotesUpgradeable.sol";
import { NoncesUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/NoncesUpgradeable.sol";
import { IERC165 } from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import { AccessControlUpgradeable } from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { ISemver } from "src/interfaces/ISemver.sol";
import { IERC7802 } from "src/interfaces/IERC7802.sol";
import { NttTokenUpgradeable } from "src/NttTokenUpgradeable.sol";

/// @title L2 WCT Token
/// @notice This contract implements the ERC20 representation of WCT token with burn, permit, and voting functionality.
///         It includes additional transfer restrictions and implements ERC-7802 for cross-chain compatibility.
///         It is designed to work with both Wormhole's NTT bridge and Superchain interop, and should be deployed
///         within the Superchain interop cluster.
/// @author WalletConnect
contract L2WCT is
    NttTokenUpgradeable,
    ERC20PermitUpgradeable,
    ERC20VotesUpgradeable,
    AccessControlUpgradeable,
    ISemver,
    IERC7802
{
    /// @notice The timestamp after which transfer restrictions are disabled
    uint256 public transferRestrictionsDisabledAfter;
    /// @notice Mapping of addresses that are allowed to transfer tokens to any address
    mapping(address account => bool isAllowed) public allowedFrom;
    /// @notice Mapping of addresses that are allowed to receive tokens from any address
    mapping(address account => bool isAllowed) public allowedTo;

    /// @notice Emitted when the allowedFrom status of an address is set
    event SetAllowedFrom(address indexed from, bool isAllowedFrom);
    /// @notice Emitted when the allowedTo status of an address is set
    event SetAllowedTo(address indexed to, bool isAllowedTo);
    /// @notice Emitted when the transfer restrictions are disabled
    event TransferRestrictionsDisabled();

    /// @notice Address of the corresponding version of this token on the remote chain
    /// @custom:deprecated This storage variable is no longer used but preserved for storage layout compatibility
    /// @custom:oz-renamed-from REMOTE_TOKEN
    address public REMOTE_TOKEN_DEPRECATED;

    /// @notice Address of the StandardBridge on this network
    /// @custom:deprecated This storage variable is no longer used but preserved for storage layout compatibility
    /// @custom:oz-renamed-from BRIDGE
    address public BRIDGE_DEPRECATED;

    /// @notice Custom errors
    error TransferRestrictionsAlreadyDisabled();
    error TransferRestricted();
    error InvalidAddress();
    error CallerNotBridge(address caller);

    /// @notice Emitted when the bridge address is changed
    event NewBridge(address previousBridge, address newBridge);

    /// @notice Semantic version
    /// @custom:semver 2.0.0
    string public constant version = "2.0.0";

    /// @notice Role for managing allowed addresses
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

    // =============== Storage ==============================================================

    struct BridgeStorage {
        address _bridge;
    }

    bytes32 private constant BRIDGE_SLOT = bytes32(uint256(keccak256("walletconnect.bridge")) - 1);

    // =============== Storage Getters/Setters ==============================================

    function _getBridgeStorage() internal pure returns (BridgeStorage storage $) {
        uint256 slot = uint256(BRIDGE_SLOT);
        assembly ("memory-safe") {
            $.slot := slot
        }
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initialization data for the contract
    struct Init {
        /// @dev The address that will be the initial admin of the contract
        address initialAdmin;
        /// @dev The address that will be the initial manager of the contract
        address initialManager;
        /// @dev Initial minter address
        address initialMinter;
        /// @dev Initial bridge address for cross-chain operations
        address initialBridge;
    }

    /// @notice Initializes the L2WCT token
    function initialize(Init memory init) public initializer {
        __NttToken_init(init.initialMinter, "WalletConnect", "WCT");
        __ERC20Permit_init("WalletConnect");
        __ERC20Votes_init();
        __AccessControl_init();

        if (init.initialAdmin == address(0)) revert InvalidAddress();
        if (init.initialManager == address(0)) revert InvalidAddress();

        // Set transfer restrictions to be disabled at type(uint256).max to be set down later
        transferRestrictionsDisabledAfter = type(uint256).max;

        _grantRole(DEFAULT_ADMIN_ROLE, init.initialAdmin);
        _grantRole(MANAGER_ROLE, init.initialManager);

        // Set initial bridge if provided
        if (init.initialBridge != address(0)) {
            _getBridgeStorage()._bridge = init.initialBridge;
            emit NewBridge(address(0), init.initialBridge);
        }
    }

    /// @custom:legacy
    /// @notice Legacy getter for the remote token. Preserved for storage layout compatibility.
    /// @custom:oz-renamed-from l1Token
    function l1TokenDeprecated() public view returns (address) {
        return REMOTE_TOKEN_DEPRECATED;
    }

    /// @custom:legacy
    /// @notice Legacy getter for the bridge. Preserved for storage layout compatibility.
    /// @custom:oz-renamed-from l2Bridge
    function l2BridgeDeprecated() public view returns (address) {
        return BRIDGE_DEPRECATED;
    }

    /// @custom:legacy
    /// @notice Legacy getter for REMOTE_TOKEN. Preserved for storage layout compatibility.
    /// @custom:oz-renamed-from remoteToken
    function remoteTokenDeprecated() public view returns (address) {
        return REMOTE_TOKEN_DEPRECATED;
    }

    /// @custom:legacy
    /// @notice Legacy getter for BRIDGE. Preserved for storage layout compatibility.
    /// @custom:oz-renamed-from bridge
    function bridgeDeprecated() public view returns (address) {
        return BRIDGE_DEPRECATED;
    }

    /// @notice ERC165 interface check function
    /// @param interfaceId Interface ID to check
    /// @return Whether or not the interface is supported by this contract
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(AccessControlUpgradeable, IERC165, NttTokenUpgradeable)
        returns (bool)
    {
        return interfaceId == type(IERC7802).interfaceId || NttTokenUpgradeable.supportsInterface(interfaceId)
            || AccessControlUpgradeable.supportsInterface(interfaceId);
    }

    /// @notice A function to set the new minter for the tokens.
    /// @param newMinter The address to add as both a minter and burner.
    function setMinter(address newMinter) external override onlyRole(DEFAULT_ADMIN_ROLE) {
        _setMinter(newMinter);
    }

    /// @notice A function to set the new bridge for cross-chain operations.
    /// @param newBridge The address to set as the bridge.
    function setBridge(address newBridge) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newBridge == address(0)) {
            revert InvalidAddress();
        }
        address previousBridge = _getBridgeStorage()._bridge;
        _getBridgeStorage()._bridge = newBridge;
        emit NewBridge(previousBridge, newBridge);
    }

    /// @dev Returns the address of the current bridge.
    function crosschainBridge() public view returns (address) {
        BridgeStorage storage $ = _getBridgeStorage();
        return $._bridge;
    }

